# Code generated by Claude
"""Tables for the Part C step 1 report from the result.json files of experiments/gravity_ff_compare.py:  python experiments/gravity_ff_report.py data/gravity_ff/<TAG> > table.md"""
import json
import sys
from pathlib import Path

root = Path(sys.argv[1])
R = {}
for p in sorted(root.glob("*/result.json")):
    R[p.parent.name] = json.loads(p.read_text())


def pair(layout, variant):
    return R.get(f"{layout}_{variant}_physics"), R.get(f"{layout}_{variant}_feedforward")


print("## Episodes\n\n| layout | variant | setting | outcome | beaker on hotplate | plan status | sim time (s) |\n|---|---|---|---|---|---|---|")
for k, r in R.items():
    print(f"| {r['layout']} | {r['variant']} | {r['mode']} | {r['outcome']} | {r['beaker_on_hotplate']} | {' '.join(x[0] for x in r['status'])} | {r['sim_time_end']:.0f} |")

for layout in ("normal", "moved"):
    for variant in ("plain", "zombie_held"):
        a, b = pair(layout, variant)
        if not a or not b:
            continue
        print(f"\n## {layout} layout, {variant}\n\n### Waypoints: the hand's distance from the target when the waypoint ended (physics / feedforward)\n")
        print("| # | prim | waypoint | position error mm (physics / ff) | angle error deg (physics / ff) | seconds (physics / ff) |\n|---|---|---|---|---|---|")
        n = max(len(a["waypoints"]), len(b["waypoints"]))
        for i in range(n):
            wa = a["waypoints"][i] if i < len(a["waypoints"]) else None
            wb = b["waypoints"][i] if i < len(b["waypoints"]) else None
            nm = (wa or wb)["name"]
            f = lambda w, k, d=2: "-" if w is None or w[k] is None else f"{w[k]:.{d}f}"
            print(f"| {i + 1} | {(wa or wb)['prim']} | {nm} | {f(wa, 'err_mm')} / {f(wb, 'err_mm')} | {f(wa, 'ang_deg')} / {f(wb, 'ang_deg')} | {f(wa, 'seconds', 1)} / {f(wb, 'seconds', 1)} |")
        print("\n### Zombie pose\n")
        for nm, r in (("physics", a), ("feedforward", b)):
            hs = "; ".join(f"{h['prim']} HOME: joint error {h['max_joint_err_rad']:.4f} rad, {h['seconds']:.1f} s" for h in r["home"])
            print(f"- {nm}: first second (empty hands at the zombie pose): largest joint error {r['first_s']['max_joint_err_rad']:.5f} rad, largest speed {r['first_s']['max_joint_speed_rad_s']:.5f} rad/s; HOME steps: {hs or 'none'}")
        print("\n### Joint torque against the motor cap (share of cap; typical = median, peak, share of ticks above 80 %)\n")
        print("| joint | cap N m | typical (physics \\| ff) | peak (physics \\| ff) | peak N m (physics \\| ff) | above 80 % of ticks (physics \\| ff) | ticks at cap (physics \\| ff) |\n|---|---|---|---|---|---|---|")
        for j, v in a["torque"].items():
            w = b["torque"][j]
            print(f"| {j} | {v['cap_nm']:.0f} | {v['typical_frac']:.3f} \\| {w['typical_frac']:.3f} | {v['peak_frac']:.2f} \\| {w['peak_frac']:.2f} | {v['peak_nm']:.2f} \\| {w['peak_nm']:.2f} | {100 * v['share_above_80']:.2f} % \\| {100 * w['share_above_80']:.2f} % | {v['ticks_at_cap']} \\| {w['ticks_at_cap']} |")
        for nm, r in (("physics", a), ("feedforward", b)):
            mom = [(j, m) for j, v in r["torque"].items() for m in v["moments_above_80"]]
            print(f"\nMoments above 80 % of a cap, {nm}: {len(mom)} listed" + ("".join(f"\n- {j}: {m['t0']:.2f}-{m['t1']:.2f} s, peak {100 * m['peak_frac']:.0f} %, phase {m['phase']}" for j, m in mom[:15])))
